use vstd::prelude::*;

verus! {

/// Enum to represent the current region relative to the diagonal:
/// - Border: x == y
/// - RegionA: x > y
/// - RegionB: y > x
#[derive(PartialEq, Eq)]
enum Region {
    Border,
    RegionA,
    RegionB,
}

/// Helper spec function to determine the region given coordinates (x,y).
spec fn region_of(x: int, y: int) -> Region {
    if x == y {
        Region::Border
    } else if x > y {
        Region::RegionA
    } else {
        Region::RegionB
    }
}

/// Main function implementing the region transitions counting logic.
/// 
/// Input:
/// - n: number of moves (≥ 0)
/// - s: vector of characters of length n, each either 'U' or 'R'
///
/// Output:
/// - number of transitions between region A and B (≤ n)
///
/// Behavior:
/// - start at (0,0), start on border region
/// - apply each move in s:
///     - 'U': y += 1
///     - 'R': x += 1
/// - count transitions between RegionA and RegionB only when moving from one region to a different region,
///   ignoring the initial boundary->region transition (does not count),
///   and ignoring staying on border or transitions involving border except storing last non-border region.
///
/// Constraints:
/// - n ≥ 0
/// - |s| = n
/// - all chars in s are 'U' or 'R'
/// - result ∈ [0, n]
fn solve(n: i8, s: Vec<char>) -> i8
    requires n >= 0,
    requires s.len() == n as usize,
    requires forall|i: usize| i < s.len() ==> s[i] == 'U' || s[i] == 'R',
    ensures result >= 0 && result <= n,
{
    let mut x: int = 0;
    let mut y: int = 0;

    // last_region remembers the last non-border region we were in
    // None means we have never left the border into a region
    let mut last_region: Option<Region> = None;
    let mut transitions: i8 = 0;

    let mut i: usize = 0;
    while i < s.len()
        invariant i <= s.len(),
        invariant x >= 0 && y >= 0,
        invariant last_region.is_none() || last_region == Some(Region::RegionA) || last_region == Some(Region::RegionB),
        invariant transitions >= 0 && transitions <= i as i8,
        decreases s.len() - i,
    {
        let c = s[i];
        if c == 'U' {
            y = y + 1;
        } else if c == 'R' {
            x = x + 1;
        }
        // Determine current region after move
        let current_region: Region = region_of(x, y);

        match current_region {
            Region::Border => {
                // On border: do not count transition
                // last_region stays unchanged (remember last non-border region)
            }
            Region::RegionA | Region::RegionB => {
                match &last_region {
                    None => {
                        // initial border->region transition does NOT count as transition
                        last_region = Some(current_region);
                    }
                    Some(last_r) => {
                        if *last_r != current_region {
                            // We moved from one region to another,
                            // so increment transitions count
                            transitions = transitions + 1;
                            last_region = Some(current_region);
                        }
                        // else same region: no transition, do nothing
                    }
                }
            }
        }

        i = i + 1;
    }

    transitions
}

} // verus

